<template><section class="page-hero"><div class="wrap"><span class="eyebrow light">WIR SIND GERNE FÜR SIE DA</span><h1>Nehmen Sie <em>Kontakt auf</em></h1><p>Sie haben Fragen oder möchten uns besuchen? Schreiben Sie uns.</p></div></section><section class="wrap section contact-layout"><div class="contact-info"><span class="eyebrow">KONTAKT & ANFAHRT</span><h2>Wir freuen uns,<br><em>von Ihnen zu hören.</em></h2><p>Ob Fragen zu Gottesdiensten, unserer Gemeinde oder einfach ein erstes Kennenlernen – wir helfen Ihnen gerne weiter.</p><div class="contact-item"><span>⌖</span><div><b>Adresse</b><p>St. Georg Koptisch-Orthodoxe Kirche<br>Wurmlinger Str. 49<br>70597 Stuttgart</p><a href="https://maps.google.com/?q=Wurmlinger+Strasse+49+70597+Stuttgart" target="_blank" rel="noreferrer">Route planen ↗</a></div></div><div class="contact-item"><span>☎</span><div><b>Telefon</b><p><a href="tel:+49711604252">0711 604252</a></p></div></div><div class="contact-item"><span>✉</span><div><b>E-Mail</b><p><a href="mailto:info@st-georg.com">info@st-georg.com</a></p></div></div></div>
<form class="contact-form" @submit.prevent="submit"><h2>Schreiben Sie uns</h2><p class="muted">Alle mit * markierten Felder sind erforderlich.</p><label>Ihr Name *<input v-model.trim="form.name" required maxlength="100" autocomplete="name" placeholder="Vor- und Nachname"></label><label>E-Mail-Adresse *<input v-model.trim="form.email" required type="email" maxlength="254" autocomplete="email" placeholder="name@beispiel.de"></label><label>Betreff<input v-model.trim="form.subject" maxlength="150" placeholder="Worum geht es?"></label><label>Ihre Nachricht *<textarea v-model.trim="form.message" required maxlength="5000" rows="5" placeholder="Wie können wir Ihnen helfen?"></textarea></label><label class="consent"><input type="checkbox" v-model="form.consent" required> Ich stimme zu, dass meine Angaben zur Bearbeitung meiner Anfrage verarbeitet werden. *</label><div v-if="!captchaConfigured" class="captcha-placeholder">Vor dem Livegang bitte den reCAPTCHA Site Key in der .env eintragen und die Domain in der Google reCAPTCHA-Konsole freischalten.</div><div v-else class="captcha-box"><div id="recaptcha-container"></div><small>Spam-Schutz durch Google reCAPTCHA.</small></div><button class="btn btn-dark" :disabled="sending || !captchaConfigured">{{sending?'Wird gesendet …':'Nachricht sicher senden →'}}</button><p v-if="status" class="form-status" role="status">{{status}}</p><p class="privacy-note">Bitte senden Sie über dieses Formular keine vertraulichen oder besonders sensiblen Informationen.</p></form></section></template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { httpsCallable } from 'firebase/functions'
import { functions, firebaseConfigured } from '../firebase'
const form=reactive({name:'',email:'',subject:'',message:'',consent:false})
const sending=ref(false),status=ref(''),captchaToken=ref(''),captchaId=ref(null)
const siteKey=import.meta.env.VITE_RECAPTCHA_SITE_KEY
const captchaConfigured=computed(()=>Boolean(firebaseConfigured && functions && siteKey))
onMounted(()=>{if(!captchaConfigured.value)return;const s=document.createElement('script');s.src='https://www.google.com/recaptcha/api.js?onload=onRecaptchaReady&render=explicit';s.async=true;s.defer=true;window.onRecaptchaReady=()=>{if(window.grecaptcha&&document.getElementById('recaptcha-container'))captchaId.value=window.grecaptcha.render('recaptcha-container',{sitekey:siteKey,callback:t=>captchaToken.value=t,'expired-callback':()=>captchaToken.value='','error-callback':()=>captchaToken.value=''})};document.head.appendChild(s)})
async function submit(){status.value='';if(!form.consent)return status.value='Bitte bestätigen Sie die Datenschutzhinweise.';if(!captchaToken.value)return status.value='Bitte bestätigen Sie zuerst reCAPTCHA.';if(!firebaseConfigured)return status.value='Der Nachrichtendienst ist noch nicht konfiguriert.';sending.value=true;try{await httpsCallable(functions,'submitContactMessage')({...form,captchaToken:captchaToken.value});status.value='Vielen Dank! Ihre Nachricht wurde sicher übermittelt.';Object.assign(form,{name:'',email:'',subject:'',message:'',consent:false});captchaToken.value='';if(captchaId.value!==null)window.grecaptcha.reset(captchaId.value)}catch(e){status.value='Die Nachricht konnte gerade nicht gesendet werden. Bitte versuchen Sie es später erneut.';captchaToken.value='';if(captchaId.value!==null)window.grecaptcha.reset(captchaId.value)}finally{sending.value=false}}
</script>
